/* Synthetic multi-site risk lab — front-end.
 *
 * Plain ES2020, no build step.  Charts are hand-written SVG so the page works
 * offline and every mark is generated by the same small helpers (so the
 * data-viz rules — thin marks, 2px surface gaps, recessive grid — are applied
 * uniformly).
 */
'use strict';

const API = '';
const STATE = {
  study: null,
  sites: [],            // selected codes
  model: 'student_t',   // dependency hypothesis in view
  scenarios: 20000,
  trainFraction: 0.7,
  seed: 2611,
  result: null,
  signature: null,
  parentSignature: null,
  stale: null,
  tab: 'data',
  pair: null,
  busy: false,
  // Per-model selected site pair for the scatter facet.
  scatterPair: {},
};

const SITE_COLORS = ['--s1', '--s2', '--s3', '--s4', '--s5'];
const MODEL_LABEL = { gaussian: 'Gaussian copula', student_t: 'Student-t copula' };
const formal = new Intl.NumberFormat('en-US', { maximumFractionDigits: 0 });
const one = new Intl.NumberFormat('en-US', { maximumFractionDigits: 1 });
const pct = (x, d = 1) =>
  x === null || x === undefined || Number.isNaN(x) ? '—' : `${(x * 100).toFixed(d)}%`;
const money = (x) =>
  x === null || x === undefined || Number.isNaN(x) ? '—' : formal.format(Math.round(x));

const $ = (sel, root = document) => root.querySelector(sel);
const $$ = (sel, root = document) => Array.from(root.querySelectorAll(sel));
const el = (tag, attrs = {}, children = []) => {
  const n = document.createElement(tag);
  for (const [k, v] of Object.entries(attrs)) {
    if (k === 'class') n.className = v;
    else if (k === 'html') n.innerHTML = v;
    else if (k === 'text') n.textContent = v;
    else if (k.startsWith('on') && typeof v === 'function') n.addEventListener(k.slice(2), v);
    else if (v !== null && v !== undefined && v !== false) n.setAttribute(k, v);
  }
  for (const c of [].concat(children)) {
    if (c === null || c === undefined) continue;
    n.append(c.nodeType ? c : document.createTextNode(String(c)));
  }
  return n;
};
const cssVar = (name, node = document.documentElement) =>
  getComputedStyle(node).getPropertyValue(name).trim();
const siteColor = (code) => {
  const i = STATE.study ? STATE.study.sites.findIndex((s) => s.code === code) : 0;
  return `var(${SITE_COLORS[((i % 5) + 5) % 5]})`;
};
const siteName = (code) => {
  const s = STATE.study?.sites.find((x) => x.code === code);
  return s ? s.name : code;
};
const monthsBetween = (a, b) => (a && b ? `${a} → ${b}` : '—');
/** Chinese rendering of a pair's tail diagnostic (the server payload is numeric). */
const pairNote = (x) => {
  const p0 = x.thresholds?.[0];
  if (!p0) return '';
  const [lo, hi] = p0.tail_ci;
  const head = `u > ${p0.threshold} 时，${p0.n_first_extreme} 个“首地点极端”月份中有 ${p0.n_dual_extreme} 个同时为两地点极端`;
  const tail = `经验尾依赖 ${p0.tail === null ? '—' : p0.tail.toFixed(3)}，95% 区间 [${lo.toFixed(2)}, ${hi.toFixed(2)}]`;
  return x.stable
    ? `${head}；${tail}。`
    : `${head}：样本太少，${tail}，区间很宽，不应据此下结论。`;
};

/* ------------------------------------------------------------------ */
/* Tooltip                                                             */
/* ------------------------------------------------------------------ */
const TT = {
  node: null,
  show(evt, title, rows) {
    if (!this.node) this.node = $('#tooltip');
    const html = [`<div class="tt-title">${escapeHtml(title)}</div>`];
    for (const r of rows) {
      html.push(
        `<div class="tt-row"><span>${
          r.swatch ? `<span class="sw" style="background:${r.swatch}"></span>` : ''
        }${escapeHtml(r.k)}</span><b>${escapeHtml(r.v)}</b></div>`
      );
    }
    this.node.innerHTML = html.join('');
    this.node.classList.add('show');
    this.move(evt);
  },
  move(evt) {
    if (!this.node) return;
    const pad = 12;
    let x = evt.clientX;
    let y = evt.clientY;
    const rect = this.node.getBoundingClientRect();
    x = Math.max(rect.width / 2 + pad, Math.min(window.innerWidth - rect.width / 2 - pad, x));
    this.node.style.left = `${x}px`;
    this.node.style.top = `${y + 6}px`;
  },
  hide() {
    if (this.node) this.node.classList.remove('show');
  },
};
const escapeHtml = (s) =>
  String(s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

/* ------------------------------------------------------------------ */
/* SVG helpers                                                         */
/* ------------------------------------------------------------------ */
const SVG_NS = 'http://www.w3.org/2000/svg';
function svgEl(tag, attrs = {}) {
  const n = document.createElementNS(SVG_NS, tag);
  for (const [k, v] of Object.entries(attrs)) {
    if (v !== null && v !== undefined) n.setAttribute(k, v);
  }
  return n;
}
function chartSvg(width, height) {
  const svg = svgEl('svg', { viewBox: `0 0 ${width} ${height}`, role: 'img', preserveAspectRatio: 'xMidYMid meet' });
  svg.style.height = 'auto';
  return svg;
}
function linearScale([d0, d1], [r0, r1]) {
  const k = (r1 - r0) / (d1 - d0 || 1);
  return (v) => r0 + (v - d0) * k;
}
function niceTicks(lo, hi, count = 5) {
  if (!Number.isFinite(lo) || !Number.isFinite(hi) || lo === hi) return [lo];
  const span = hi - lo;
  const step0 = span / count;
  const mag = Math.pow(10, Math.floor(Math.log10(step0)));
  const norm = step0 / mag;
  const step = (norm >= 5 ? 10 : norm >= 2.5 ? 5 : norm >= 1.5 ? 2 : 1) * mag;
  const start = Math.ceil(lo / step) * step;
  const out = [];
  for (let v = start; v <= hi + step * 1e-9; v += step) out.push(+v.toFixed(10));
  return out;
}
const compact = (v) => {
  const a = Math.abs(v);
  if (a >= 1e6) return `${(v / 1e6).toFixed(a >= 1e7 ? 0 : 1)}M`;
  if (a >= 1e4) return `${(v / 1e3).toFixed(0)}K`;
  if (a >= 1000) return `${(v / 1e3).toFixed(1)}K`;
  return formal.format(v);
};
function legendItems(items) {
  return el(
    'div',
    { class: 'legend' },
    items.map((it) =>
      el('span', { class: 'legend-item' }, [
        it.dash
          ? el('span', { class: 'legend-dash' })
          : el('span', {
              class: it.line ? 'legend-line' : 'legend-swatch',
              style: `background:${it.color}`,
            }),
        it.label,
      ])
    )
  );
}

/* ------------------------------------------------------------------ */
/* Charts                                                              */
/* ------------------------------------------------------------------ */

/** Multi-series line chart over months. data: [{code, points:[[ym,val]]}] */
function lineChart(container, series, opts = {}) {
  const width = opts.width || 1100;
  const height = opts.height || 300;
  const m = { t: 14, r: opts.rightPad || 54, b: 30, l: 58 };
  const svg = chartSvg(width, height);
  const all = series.flatMap((s) => s.points.filter((p) => p[1] !== null));
  if (!all.length) {
    container.append(el('p', { class: 'empty', text: '无可用观测' }));
    return;
  }
  const xLabels = series[0].points.map((p) => p[0]);
  const xi = new Map(xLabels.map((ym, i) => [ym, i]));
  const yMax = Math.max(...all.map((p) => p[1]));
  const yMin = opts.zeroBase === false ? Math.min(...all.map((p) => p[1])) * 0.98 : 0;
  const xs = linearScale([0, xLabels.length - 1], [m.l, width - m.r]);
  const ys = linearScale([yMin, yMax * 1.02], [height - m.b, m.t]);

  const ticks = niceTicks(yMin, yMax * 1.02, 5);
  for (const t of ticks) {
    const y = ys(t);
    svg.append(svgEl('line', { x1: m.l, x2: width - m.r, y1: y, y2: y, class: 'gridline' }));
    const label = svgEl('text', { x: m.l - 8, y: y + 3.5, 'text-anchor': 'end' });
    label.textContent = compact(t);
    label.setAttribute('class', 'axis');
    svg.append(label);
  }
  svg.append(svgEl('line', { x1: m.l, x2: width - m.r, y1: height - m.b, y2: height - m.b, class: 'baseline' }));

  const xTickCount = Math.min(8, xLabels.length);
  for (let i = 0; i < xTickCount; i++) {
    const idx = Math.round((i * (xLabels.length - 1)) / Math.max(1, xTickCount - 1));
    const t = svgEl('text', { x: xs(idx), y: height - m.b + 17, 'text-anchor': 'middle', class: 'axis' });
    t.textContent = xLabels[idx];
    svg.append(t);
  }

  const dash = opts.dashPattern || [5, 4];
  for (const s of series) {
    const path = s.points
      .map((p, i) => (p[1] === null ? null : [xs(i), ys(p[1])]))
      .filter(Boolean);
    if (!path.length) continue;
    if (s.area) {
      const d =
        `M ${path[0][0]} ${height - m.b} ` +
        path.map(([x, y]) => `L ${x} ${y}`).join(' ') +
        ` L ${path[path.length - 1][0]} ${height - m.b} Z`;
      svg.append(svgEl('path', { d, class: 'series-area', fill: s.color }));
    }
    const d = path.map(([x, y], i) => `${i ? 'L' : 'M'} ${x} ${y}`).join(' ');
    svg.append(
      svgEl('path', {
        d,
        class: 'series-line',
        stroke: s.color,
        'stroke-dasharray': s.dash ? (s.dash === true ? dash.join(' ') : s.dash) : null,
      })
    );
  }
  if (opts.markers) {
    for (const mk of opts.markers) {
      const x = xs(mk.index);
      svg.append(svgEl('line', { x1: x, x2: x, y1: m.t, y2: height - m.b, class: 'ref-line' }));
      const t = svgEl('text', { x: x + 5, y: m.t + 11, class: 'direct-label muted' });
      t.textContent = mk.label;
      svg.append(t);
    }
  }
  container.append(svg);
  attachLineHover(svg, { series, xs, ys, xLabels, width, height, m, opts });
}

function attachLineHover(svg, ctx) {
  const { series, xs, xLabels, m, height, width, opts } = ctx;
  const cross = svgEl('line', { y1: m.t, y2: height - m.b, class: 'ref-line', opacity: 0 });
  cross.setAttribute('stroke-dasharray', '3 3');
  svg.append(cross);
  const dots = series.map((s) => {
    const c = svgEl('circle', { r: 4, class: 'dot', fill: s.color, opacity: 0 });
    svg.append(c);
    return c;
  });
  const hit = svgEl('rect', {
    x: m.l,
    y: m.t,
    width: width - m.l - m.r,
    height: height - m.t - m.b,
    fill: 'transparent',
    style: 'cursor:crosshair',
  });
  svg.append(hit);
  hit.addEventListener('mousemove', (evt) => {
    const rect = svg.getBoundingClientRect();
    const scale = width / rect.width;
    const px = (evt.clientX - rect.left) * scale;
    let best = 0;
    let bd = Infinity;
    for (let i = 0; i < xLabels.length; i++) {
      const d = Math.abs(xs(i) - px);
      if (d < bd) { bd = d; best = i; }
    }
    const x = xs(best);
    cross.setAttribute('x1', x);
    cross.setAttribute('x2', x);
    cross.setAttribute('opacity', 1);
    const rows = [];
    series.forEach((s, j) => {
      const v = s.points[best]?.[1];
      const dot = dots[j];
      if (v === null || v === undefined) {
        dot.setAttribute('opacity', 0);
      } else {
        dot.setAttribute('cx', x);
        dot.setAttribute('cy', ctx.ys(v));
        dot.setAttribute('opacity', 1);
        rows.push({ k: s.short || s.label, v: money(v), swatch: s.color });
      }
    });
    if (!rows.length) { TT.hide(); return; }
    TT.show(evt, xLabels[best], rows);
  });
  hit.addEventListener('mouseleave', () => {
    cross.setAttribute('opacity', 0);
    dots.forEach((d) => d.setAttribute('opacity', 0));
    TT.hide();
  });
}

/** Grouped bar chart. groups: [{label, values:[...]}], series: [{label,color}] */
/** Stacked count distribution: P(#sites over own q95 = k). */
function countChart(container, models, observed, codes) {
  const width = 560;
  const height = 250;
  const m = { t: 24, r: 16, b: 40, l: 84 };
  const svg = chartSvg(width, height);
  const rows = models.length + (observed ? 1 : 0);
  const cats = Array.from({ length: codes.length + 1 }, (_, i) => i);
  const allVals = models.flatMap((x) => x.dist);
  if (observed) allVals.push(...observed);
  const xMax = Math.max(...allVals, 0.001) * 1.15;
  const xs = linearScale([0, xMax], [m.l, width - m.r]);
  for (const t of niceTicks(0, xMax, 4)) {
    const x = xs(t);
    svg.append(svgEl('line', { x1: x, x2: x, y1: m.t, y2: height - m.b, class: 'gridline' }));
    const tx = svgEl('text', { x, y: height - m.b + 16, 'text-anchor': 'middle', class: 'axis' });
    tx.textContent = `${(t * 100).toFixed(t < 0.01 ? 2 : 1)}%`;
    svg.append(tx);
  }
  svg.append(svgEl('line', { x1: m.l, x2: m.l, y1: m.t, y2: height - m.b, class: 'baseline' }));
  const rowH = (height - m.t - m.b) / rows;
  const barH = Math.min(22, rowH - 6);
  const labels = [...models.map((x) => x.label), ...(observed ? ['观测月份'] : [])];
  labels.forEach((lab, ri) => {
    const y = m.t + ri * rowH + (rowH - barH) / 2;
    const tx = svgEl('text', { x: m.l - 8, y: y + barH / 2 + 3.5, 'text-anchor': 'end', class: 'axis' });
    tx.textContent = lab;
    svg.append(tx);
    const dist = ri < models.length ? models[ri].dist : observed;
    cats.forEach((k) => {
      const v = dist[k] || 0;
      if (v <= 0) return;
      const x0 = k === 0 ? m.l : xs(0) + (k === 0 ? 0 : 0);
      const prev = cats.slice(0, k).reduce((a, kk) => a + (dist[kk] || 0), 0);
      const x = xs(prev);
      const w = Math.max(1, xs(prev + v) - x - 2); // 2px surface gap
      const fill = k === codes.length ? 'var(--critical)' : k >= 2 ? 'var(--s2)' : k === 1 ? 'var(--s1)' : 'var(--grid)';
      const rect = svgEl('rect', { x, y, width: w, height: barH, rx: 2, fill, style: 'cursor:pointer' });
      rect.addEventListener('mousemove', (evt) => {
        TT.show(evt, lab, [
          { k: `Exactly ${k} site${k === 1 ? '' : 's'} over own q95`, v: pct(v, 2) },
          { k: 'Cumulative ≥', v: pct(dist.slice(k).reduce((a, b) => a + b, 0), 2) },
        ]);
      });
      rect.addEventListener('mouseleave', () => TT.hide());
      svg.append(rect);
    });
  });
  container.append(svg);
  container.append(
    el('p', {
      class: 'chart-note',
      text: '每个条形的分段 = 恰好有 k 个地点同时超过各自训练期 q95 的概率。最右深红段 = 全部地点同时超限。',
    })
  );
}

/** Scatter of two site losses with q95 reference lines. */
function scatterChart(container, series, opts = {}) {
  const width = opts.width || 540;
  const height = opts.height || 330;
  const m = { t: 18, r: 20, b: 44, l: 56 };
  const svg = chartSvg(width, height);
  const pts = series.points;
  const xMax = Math.max(...pts.map((p) => p[0]), ...opts.q95) * 1.08;
  const yMax = Math.max(...pts.map((p) => p[1]), ...opts.q95) * 1.08;
  const xs = linearScale([0, xMax], [m.l, width - m.r]);
  const ys = linearScale([0, yMax], [height - m.b, m.t]);
  for (const t of niceTicks(0, yMax, 4)) {
    svg.append(svgEl('line', { x1: m.l, x2: width - m.r, y1: ys(t), y2: ys(t), class: 'gridline' }));
    const tx = svgEl('text', { x: m.l - 8, y: ys(t) + 3.5, 'text-anchor': 'end', class: 'axis' });
    tx.textContent = compact(t);
    svg.append(tx);
  }
  for (const t of niceTicks(0, xMax, 4)) {
    const tx = svgEl('text', { x: xs(t), y: height - m.b + 16, 'text-anchor': 'middle', class: 'axis' });
    tx.textContent = compact(t);
    svg.append(tx);
  }
  svg.append(svgEl('line', { x1: m.l, x2: width - m.r, y1: height - m.b, y2: height - m.b, class: 'baseline' }));
  svg.append(svgEl('line', { x1: m.l, x2: m.l, y1: m.t, y2: height - m.b, class: 'baseline' }));
  svg.append(svgEl('line', { x1: xs(opts.q95[0]), x2: xs(opts.q95[0]), y1: m.t, y2: height - m.b, class: 'ref-line' }));
  svg.append(svgEl('line', { x1: m.l, x2: width - m.r, y1: ys(opts.q95[1]), y2: ys(opts.q95[1]), class: 'ref-line' }));
  for (const [x, y] of pts) {
    const c = svgEl('circle', {
      cx: xs(x), cy: ys(y), r: 2.8, fill: opts.color, opacity: 0.55, class: 'dot',
    });
    c.addEventListener('mousemove', (evt) =>
      TT.show(evt, `${opts.xLabel} × ${opts.yLabel}`, [
        { k: opts.xLabel, v: money(x), swatch: opts.color },
        { k: opts.yLabel, v: money(y) },
        { k: '两者同时 > q95', v: x > opts.q95[0] && y > opts.q95[1] ? '是' : '否' },
      ])
    );
    c.addEventListener('mouseleave', () => TT.hide());
    svg.append(c);
  }
  const ax = svgEl('text', { x: width - m.r, y: height - 6, 'text-anchor': 'end', class: 'axis-label' });
  ax.textContent = opts.xLabel;
  svg.append(ax);
  const ay = svgEl('text', { x: 12, y: m.t + 4, class: 'axis-label' });
  ay.textContent = opts.yLabel;
  svg.append(ay);
  container.append(svg);
}

/** Survival curve: P(total > x) on log y. */
function survivalChart(container, series, opts = {}) {
  const width = opts.width || 640;
  const height = opts.height || 300;
  const m = { t: 20, r: 60, b: 42, l: 58 };
  const svg = chartSvg(width, height);
  const all = series.flatMap((s) => s.points);
  if (!all.length) return;
  const xMin = Math.min(...all.map((p) => p[0]));
  const xMax = Math.max(...all.map((p) => p[0]));
  const ysVals = all.map((p) => p[1]).filter((v) => v > 0);
  const yMin = Math.min(...ysVals);
  const xs = linearScale([xMin, xMax], [m.l, width - m.r]);
  const ys = linearScale([Math.log10(yMin), Math.log10(1)], [height - m.b, m.t]);
  for (const t of [0.001, 0.01, 0.05, 0.1, 0.5]) {
    const y = ys(Math.log10(t));
    svg.append(svgEl('line', { x1: m.l, x2: width - m.r, y1: y, y2: y, class: 'gridline' }));
    const tx = svgEl('text', { x: m.l - 8, y: y + 3.5, 'text-anchor': 'end', class: 'axis' });
    tx.textContent = `${(t * 100).toFixed(1)}%`;
    svg.append(tx);
  }
  for (const t of niceTicks(xMin, xMax, 4)) {
    const tx = svgEl('text', { x: xs(t), y: height - m.b + 16, 'text-anchor': 'middle', class: 'axis' });
    tx.textContent = compact(t);
    svg.append(tx);
  }
  svg.append(svgEl('line', { x1: m.l, x2: width - m.r, y1: height - m.b, y2: height - m.b, class: 'baseline' }));
  series.forEach((s) => {
    const pts = s.points.filter((p) => p[1] > 0);
    if (!pts.length) return;
    const d = pts
      .map(([x, p], i) => `${i ? 'L' : 'M'} ${xs(x)} ${ys(Math.log10(p))}`)
      .join(' ');
    svg.append(svgEl('path', { d, class: 'series-line', stroke: s.color, 'stroke-dasharray': s.dash ? '5 4' : null }));
    const last = pts[pts.length - 1];
    const lab = svgEl('text', {
      x: xs(last[0]) + 7,
      y: ys(Math.log10(last[1])) + 3.5,
      class: 'direct-label muted',
    });
    lab.textContent = s.short;
    svg.append(lab);
  });
  const ax = svgEl('text', { x: width - m.r, y: height - 6, 'text-anchor': 'end', class: 'axis-label' });
  ax.textContent = '总损失 (合成单位)';
  svg.append(ax);
  container.append(svg);
}

/** Histogram of simulated total loss, two models overlaid as outlined steps. */
function histogramChart(container, edges, series) {
  const width = 660;
  const height = 260;
  const m = { t: 18, r: 20, b: 40, l: 52 };
  const svg = chartSvg(width, height);
  const maxCount = Math.max(...series.flatMap((s) => s.counts));
  const xs = linearScale([edges[0], edges[edges.length - 1]], [m.l, width - m.r]);
  const ys = linearScale([0, maxCount * 1.06], [height - m.b, m.t]);
  for (const t of niceTicks(0, maxCount * 1.06, 4)) {
    svg.append(svgEl('line', { x1: m.l, x2: width - m.r, y1: ys(t), y2: ys(t), class: 'gridline' }));
    const tx = svgEl('text', { x: m.l - 8, y: ys(t) + 3.5, 'text-anchor': 'end', class: 'axis' });
    tx.textContent = compact(t);
    svg.append(tx);
  }
  for (const t of niceTicks(edges[0], edges[edges.length - 1], 5)) {
    const tx = svgEl('text', { x: xs(t), y: height - m.b + 16, 'text-anchor': 'middle', class: 'axis' });
    tx.textContent = compact(t);
    svg.append(tx);
  }
  svg.append(svgEl('line', { x1: m.l, x2: width - m.r, y1: height - m.b, y2: height - m.b, class: 'baseline' }));
  series.forEach((s) => {
    const d = s.counts
      .map((c, i) => {
        const x0 = xs(edges[i]);
        const x1 = xs(edges[i + 1]);
        const y = ys(c);
        return `${i ? 'L' : 'M'} ${x0} ${height - m.b} L ${x0} ${y} L ${x1} ${y} L ${x1} ${height - m.b}`;
      })
      .join(' ');
    svg.append(
      svgEl('path', {
        d,
        fill: 'none',
        stroke: s.color,
        'stroke-width': 2,
        'stroke-linejoin': 'round',
        'stroke-dasharray': s.dash ? '5 4' : null,
      })
    );
  });
  const hit = svgEl('rect', {
    x: m.l, y: m.t, width: width - m.l - m.r, height: height - m.t - m.b, fill: 'transparent',
  });
  hit.addEventListener('mousemove', (evt) => {
    const rect = svg.getBoundingClientRect();
    const scale = width / rect.width;
    const px = (evt.clientX - rect.left) * scale;
    let bi = 0;
    let bd = Infinity;
    for (let i = 0; i < edges.length - 1; i++) {
      const c = (xs(edges[i]) + xs(edges[i + 1])) / 2;
      const d = Math.abs(c - px);
      if (d < bd) { bd = d; bi = i; }
    }
    const last = bi === edges.length - 2;
    TT.show(evt, last ? `总损失 ≥ ${compact(edges[bi])}（含更高尾部）` : `总损失 ${compact(edges[bi])} – ${compact(edges[bi + 1])}`, [
      ...series.map((s) => ({ k: s.label, v: formal.format(s.counts[bi]), swatch: s.color })),
      { k: '观测月份', v: formal.format(series[0].observed?.[bi] ?? 0) },
    ]);
  });
  hit.addEventListener('mouseleave', () => TT.hide());
  svg.append(hit);
  container.append(svg);
}

/* ------------------------------------------------------------------ */
/* API                                                                 */
/* ------------------------------------------------------------------ */
async function api(path, opts = {}) {
  const res = await fetch(API + path, {
    headers: { 'content-type': 'application/json' },
    ...opts,
  });
  const text = await res.text();
  let body = null;
  try { body = text ? JSON.parse(text) : null; } catch { body = text; }
  if (!res.ok) {
    const err = new Error(body?.detail?.message || body?.detail || `HTTP ${res.status}`);
    err.status = res.status;
    err.body = body;
    throw err;
  }
  return body;
}

