function renderStatus() {
  const wrap = el('div', { class: 'controls-status' });
  if (!STATE.result) {
    wrap.append(el('span', { text: '尚未拟合。选择地点后点击“开始拟合”。' }));
    return wrap;
  }
  const p = STATE.result;
  wrap.append(
    el('span', {}, [
      el('b', { text: `${p.sites.length} 个地点` }),
      ` · 共同观测 ${p.calendar.joint_months} 月 `,
      el('span', { class: 'signature', text: `(${p.calendar.common_range[0]} → ${p.calendar.common_range[1]})` }),
    ])
  );
  wrap.append(
    el('span', {}, [
      '训练 ',
      el('b', { text: `${p.calendar.train_months} 月` }),
      ` (${monthsBetween(...p.calendar.train_range)}) · 评估 `,
      el('b', { text: `${p.calendar.eval_months} 月` }),
      ` (${monthsBetween(...p.calendar.eval_range)})`,
    ])
  );
  wrap.append(
    el('span', {}, [
      '成员版本 ',
      el('b', { text: p.membership.label }),
      p.membership.declared ? '' : '（自定义组合）',
    ])
  );
  wrap.append(el('span', { class: 'signature', text: `signature ${STATE.signature}` }));
  return wrap;
}

function clamp(v, lo, hi) {
  return Math.min(hi, Math.max(lo, v));
}

function onSiteToggle(evt) {
  const code = evt.target.value;
  if (evt.target.checked) {
    if (!STATE.sites.includes(code)) STATE.sites.push(code);
  } else {
    STATE.sites = STATE.sites.filter((c) => c !== code);
  }
  markStale();
  renderControls();
  renderView();
}

function markStale() {
  const banner = $('#staleBanner');
  banner.innerHTML = '';
  if (!STATE.result) return;
  if (sameSites(STATE.sites, STATE.result.sites)) {
    STATE.stale = null;
    return;
  }
  const prev = STATE.result;
  const prevVersion = prev.membership.label;
  const nextVersion = declaredVersion(STATE.sites);
  const added = STATE.sites.filter((c) => !prev.sites.includes(c));
  const removed = prev.sites.filter((c) => !STATE.sites.includes(c));
  STATE.stale = { prev, added, removed, prevVersion, nextVersion };
  banner.append(
    el('div', { class: 'banner banner-warn', role: 'alert' }, [
      el('span', { class: 'banner-icon', text: '⚠' }),
      el('div', { class: 'banner-body' }, [
        el('strong', { text: '站点集合已改变，旧场景不能追加一列继续使用' }),
        el('div', {
          html:
            `已选地点从 <b>${escapeHtml(prevVersion)}</b> 变为 <b>${escapeHtml(nextVersion)}</b>` +
            (added.length ? `，新增 ${added.map(escapeHtml).join('、')}` : '') +
            (removed.length ? `，移除 ${removed.map(escapeHtml).join('、')}` : '') +
            `。新地点会改变<b>共同观测月份</b>、边际参数和尾部依赖结构；因此下面的图表仍是旧拟合（${prev.sites.length} 个地点），` +
            '必须重新拟合才能得到同一个联合样本。',
        }),
        el('div', { class: 'banner-actions' }, [
          el('button', { class: 'btn btn-primary btn-sm', type: 'button', text: '按新地点重新拟合', onclick: runFit }),
          el('button', {
            class: 'btn btn-ghost btn-sm',
            type: 'button',
            text: '还原旧选择',
            onclick: () => {
              STATE.sites = [...prev.sites];
              markStale();
              renderControls();
              renderView();
            },
          }),
        ]),
      ]),
    ])
  );
}

const sameSites = (a, b) => a.length === b.length && [...a].sort().every((x, i) => x === [...b].sort()[i]);
function declaredVersion(sites) {
  const vs = STATE.study?.study?.membership_versions || [];
  const hit = vs.find((v) => sameSites(v.sites, sites));
  return hit ? hit.label : 'custom-selection';
}

async function runFit() {
  if (STATE.busy) return;
  if (STATE.sites.length < 2) {
    toast('至少选择两个地点', 'err');
    return;
  }
  STATE.busy = true;
  renderControls();
  const view = $('#view');
  view.innerHTML = '';
  view.append(
    el('div', { class: 'panel empty' }, [
      el('span', { class: 'spinner' }),
      el('h2', { text: '正在联合拟合' }),
      el('p', {
        text: `${STATE.sites.length} 个地点 · ${STATE.scenarios.toLocaleString()} 个场景 · 边际 → 共同观测相关矩阵 → 两类 copula → 场景生成`,
      }),
    ])
  );
  try {
    const wanted = [...STATE.sites];
    const body = {
      sites: wanted,
      scenarios: STATE.scenarios,
      seed: STATE.seed,
      train_fraction: STATE.trainFraction,
    };
    const res = await api('/api/fit', { method: 'POST', body: JSON.stringify(body) });
    STATE.result = res;
    STATE.signature = res.signature;
    STATE.parentSignature = null;
    STATE.stale = null;
    STATE.pair = null;
    STATE.scatterPair = {};
    STATE.busy = false;
    markStale();
    renderControls();
    renderView();
    toast(`拟合完成 · 共同观测 ${res.calendar.joint_months} 个月`);
  } catch (e) {
    STATE.busy = false;
    renderControls();
    renderView();
    toast(`拟合失败：${e.message}`, 'err');
  }
}

/* ------------------------------------------------------------------ */
/* Toast                                                               */
/* ------------------------------------------------------------------ */
let toastTimer = null;
function toast(msg, kind = 'ok') {
  let node = $('#toast');
  if (!node) {
    node = el('div', { id: 'toast', class: 'banner', style: 'position:fixed;right:20px;bottom:20px;z-index:80;max-width:420px;margin:0;box-shadow:0 8px 30px rgba(0,0,0,.18)' });
    document.body.append(node);
  }
  node.className = `banner ${kind === 'err' ? 'banner-err' : 'banner-ok'}`;
  node.style.position = 'fixed';
  node.style.right = '20px';
  node.style.bottom = '20px';
  node.style.zIndex = '80';
  node.style.maxWidth = '420px';
  node.style.margin = '0';
  node.style.boxShadow = '0 8px 30px rgba(0,0,0,.18)';
  node.innerHTML = '';
  node.append(el('span', { class: 'banner-icon', text: kind === 'err' ? '✕' : '✓' }));
  node.append(el('div', { class: 'banner-body', text: msg }));
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => { node.remove(); }, 4200);
}

/* ------------------------------------------------------------------ */
/* Views                                                               */
/* ------------------------------------------------------------------ */
function renderView() {
  const view = $('#view');
  view.innerHTML = '';
  if (!STATE.study) return;
  if (!STATE.result) {
    view.append(renderIntro());
    return;
  }
  if (STATE.tab === 'data') view.append(renderDataTab());
  else if (STATE.tab === 'marginals') view.append(renderMarginalsTab());
  else if (STATE.tab === 'dependence') view.append(renderDependenceTab());
  else if (STATE.tab === 'scenarios') view.append(renderScenariosTab());
  else if (STATE.tab === 'validation') view.append(renderValidationTab());
  else if (STATE.tab === 'downloads') view.append(renderDownloadsTab());
}

