function statTile(label, value, sub, kind) {
  const val = el('div', { class: 'value' });
  val.append(document.createTextNode(value));
  const node = el('div', { class: 'stat' }, [el('div', { class: 'label', text: label }), val]);
  if (sub) node.append(el('div', { class: `delta ${kind === 'warn' ? 'warn' : kind === 'bad' ? 'bad' : ''}`, text: sub }));
  return node;
}

/* ------------------------------------------------------------------ */
/* Tabs, theme, init                                                   */
/* ------------------------------------------------------------------ */
function setupTabs() {
  $$('.tab').forEach((b) => {
    b.addEventListener('click', () => {
      $$('.tab').forEach((x) => x.setAttribute('aria-selected', String(x === b)));
      STATE.tab = b.dataset.tab;
      renderView();
    });
  });
}

function setupTheme() {
  const saved = localStorage.getItem('risk-theme');
  if (saved) document.documentElement.dataset.theme = saved;
  $('#themeBtn').addEventListener('click', () => {
    const cur = document.documentElement.dataset.theme;
    const next = cur === 'dark' ? 'light' : cur === 'light' ? '' : matchMedia('(prefers-color-scheme: dark)').matches ? 'light' : 'dark';
    if (next) document.documentElement.dataset.theme = next;
    else delete document.documentElement.dataset.theme;
    localStorage.setItem('risk-theme', next || '');
    renderControls();
    renderView();
  });
}

async function init() {
  setupTabs();
  setupTheme();
  document.addEventListener('mousemove', (e) => { if (TT.node?.classList.contains('show')) TT.move(e); });
  try {
    const data = await api('/api/study');
    STATE.study = data;
    const declared = data.study.membership_versions.find((v) => v.label === 'core-four') || data.study.membership_versions[0];
    STATE.sites = declared ? [...declared.sites] : data.sites.slice(0, 4).map((s) => s.code);
    renderControls();
    renderView();
  } catch (e) {
    $('#view').innerHTML = '';
    $('#view').append(el('div', { class: 'banner banner-err' }, [
      el('span', { class: 'banner-icon', text: '✕' }),
      el('div', { class: 'banner-body', html: `<strong>无法载入合成数据</strong>${escapeHtml(e.message)}` }),
    ]));
  }
}

init();

// Small debug surface used by the browser smoke test and by manual console
// inspection.  It exposes read-only state and the two entry points; it does not
// change behaviour.
window.__risk = { STATE, runFit, renderView, api };
